package ru.local.jarvis;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.database.Cursor;import android.provider.ContactsContract;import android.telephony.PhoneNumberUtils;import android.widget.*;import java.util.*;
public class ActionScreen extends Activity{
 String tr(String ru,String en){String language=item==null?getIntent().getStringExtra("language"):item.action.optString("language");return "en".equals(language)?en:ru;} Actions.Item item;String number,name;boolean ended;
 public void onCreate(Bundle b){super.onCreate(b);item=Actions.take(getIntent().getStringExtra("id"));getSystemService(NotificationManager.class).cancel(83);if(item==null){Toast.makeText(this,tr("Действие истекло. Повторите команду.","This action expired. Please repeat the command."),1).show();finish();return;}setTitle(tr("Джарвис","Jarvis"));if(item.action.optString("kind").equals("route")){if(item.action.optString("map_provider").equals("yandex"))yandexRoute();else openRoute();}else resolve();}
 void openRoute(){try{boolean yandex=item.action.optString("map_provider").equals("yandex");startActivity(new Intent(Intent.ACTION_VIEW,Actions.route(item.action)).setPackage(yandex?"ru.yandex.yandexmaps":"com.google.android.apps.maps"));done(tr("Открыто построение маршрута","Directions opened"));}catch(Exception e){error(tr("Не удалось открыть Карты. Проверьте, установлено ли приложение.","Could not open Maps. Check that the app is installed."));}}
 void yandexRoute(){TextView wait=new TextView(this);wait.setPadding(32,32,32,32);wait.setText(tr("Определяю пункт назначения…","Finding the destination…"));setContentView(wait);new Thread(()->{try{android.location.Geocoder geocoder=new android.location.Geocoder(this,java.util.Locale.getDefault());java.util.List<android.location.Address> locations=geocoder.getFromLocationName(item.action.getString("target"),5);if(locations==null||locations.isEmpty()){runOnUiThread(()->error(tr("Адрес не найден. Уточните город и пункт назначения.","Address not found. Please specify the city and destination.")));return;}runOnUiThread(()->{if(isFinishing())return;if(locations.size()==1){chooseLocation(locations.get(0));return;}String[] labels=new String[locations.size()];for(int i=0;i<labels.length;i++)labels[i]=locations.get(i).getAddressLine(0);new AlertDialog.Builder(this).setTitle(tr("Выберите пункт назначения","Choose the destination")).setItems(labels,(d,w)->chooseLocation(locations.get(w))).setNegativeButton(tr("Отмена","Cancel"),(d,w)->done(tr("Построение маршрута отменено","Directions cancelled"))).show();});}catch(Exception e){runOnUiThread(()->error(tr("Не удалось определить адрес. Проверьте соединение и уточните пункт назначения.","Could not find the address. Check your connection and specify the destination.")));}}).start();}
 void chooseLocation(android.location.Address a){try{item.action.put("latitude",a.getLatitude());item.action.put("longitude",a.getLongitude());openRoute();}catch(Exception e){error(tr("Не удалось построить маршрут","Could not open directions"));}}
 void resolve(){String target=item.action.optString("target").trim();if(target.matches("[+0-9 ()-]{5,30}")){number=PhoneNumberUtils.normalizeNumber(target);name=target;confirm();return;}if(checkSelfPermission("android.permission.READ_CONTACTS")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.READ_CONTACTS"},31);return;}
  new Thread(()->{ArrayList<String[]> found=new ArrayList<>();try(Cursor cur=getContentResolver().query(Uri.withAppendedPath(ContactsContract.CommonDataKinds.Phone.CONTENT_FILTER_URI,Uri.encode(target)),new String[]{ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER},null,null,null)){
   Set<String> seen=new HashSet<>();if(cur!=null)while(cur.moveToNext()&&found.size()<15){String n=PhoneNumberUtils.normalizeNumber(cur.getString(1));if(seen.add(n))found.add(new String[]{cur.getString(0),n});}
  }catch(Exception e){runOnUiThread(()->error(tr("Не удалось прочитать контакты","Could not read contacts")));return;}
  runOnUiThread(()->{if(found.isEmpty()){error(tr("Контакт не найден. Назовите точное имя или номер.","Contact not found. Please say the exact name or phone number."));return;}if(found.size()==1){name=found.get(0)[0];number=found.get(0)[1];confirm();return;}String[] labels=new String[found.size()];for(int i=0;i<labels.length;i++)labels[i]=found.get(i)[0]+" · "+found.get(i)[1];new AlertDialog.Builder(this).setTitle(tr("Какому контакту позвонить?","Which contact should I call?")).setItems(labels,(d,which)->{name=found.get(which)[0];number=found.get(which)[1];confirm();}).setNegativeButton(tr("Отмена","Cancel"),(d,w)->done(tr("Звонок отменён пользователем","Call cancelled"))).setOnCancelListener(d->done(tr("Звонок отменён пользователем","Call cancelled"))).show();});}).start();}
 void confirm(){if(number==null||!number.matches("\\+?[0-9]{5,20}")){error(tr("Не удалось безопасно определить номер. Наберите его вручную.","Could not determine a valid phone number. Please dial it manually."));return;}new AlertDialog.Builder(this).setTitle(tr("Позвонить?","Place this call?")).setMessage(name+"\n"+number).setPositiveButton(tr("Позвонить","Call"),(d,w)->{if(checkSelfPermission("android.permission.CALL_PHONE")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.CALL_PHONE"},32);else call();}).setNegativeButton(tr("Отмена","Cancel"),(d,w)->done(tr("Звонок отменён пользователем","Call cancelled"))).setOnCancelListener(d->done(tr("Звонок отменён пользователем","Call cancelled"))).show();}
 void call(){try{startActivity(new Intent(Intent.ACTION_CALL,Uri.fromParts("tel",number,null)));done(tr("Подтверждённый вызов передан телефонному приложению","Confirmed call sent to the phone app"));}catch(Exception e){error(tr("Не удалось начать звонок","Could not start the call"));}}
 public void onRequestPermissionsResult(int request,String[] p,int[] g){super.onRequestPermissionsResult(request,p,g);if(g.length==0||g[0]!=0){error(tr("Нужное разрешение не выдано","The required permission was not granted"));return;}if(request==31)resolve();if(request==32)call();}
 void error(String text){if(isFinishing())return;new AlertDialog.Builder(this).setTitle(tr("Джарвис","Jarvis")).setMessage(text).setPositiveButton(tr("Закрыть","Close"),(d,w)->done(text)).setOnCancelListener(d->done(text)).show();}
 void done(String result){if(!ended&&item!=null){ended=true;Actions.report(this,item,result);Assistant.last+="\n\n"+result;}finish();}
 public void onBackPressed(){done(tr("Действие отменено пользователем","Action cancelled"));}
}
